#include <stdio.h>
static void swap_bytes(void *left,void *right,size_t count){unsigned char *a=left,*b=right;for(size_t i=0;i<count;++i){unsigned char t=a[i];a[i]=b[i];b[i]=t;}}
int main(void) {
    int a,b; if(scanf("%d%d",&a,&b)!=2)return 1;
    swap_bytes(&a,&b,sizeof a);
    printf("%d %d\n",a,b);
    return 0;
}
